             if (touched.has(name)) {
               syncField(name, true);
             } else {
               syncField(name, false);
             }
           });
         });

         form.addEventListener('submit', (event) => {
           const nameOrder = Object.keys(fields);
           const firstInvalid = nameOrder.find((name) => !syncField(name, true));

           if (firstInvalid) {
             event.preventDefault();
             fields[firstInvalid].input.focus();
             return;
           }
         });
       })();
