         --border-strong: #9badbf;
         --accent: #275efe;
         --accent-strong: #1c46d1;
         --shadow: 0 24px 60px rgba(16, 32, 51, 0.12);
         --error: #b42318;
         --success: #067647;
         --radius: 22px;
         --focus: 0 0 0 4px rgba(39, 94, 254, 0.18);
       }

       * {
         box-sizing: border-box;
       }

       html {
         scroll-behavior: smooth;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         line-height: 1.5;
         color: var(--text);
         background:
           radial-gradient(circle at top left, rgba(39, 94, 254, 0.12), transparent 40%),
           linear-gradient(180deg, #f7faff 0%, var(--bg) 100%);
       }

       a {
         color: inherit;
       }

       .skip-link {
         position: absolute;
         top: 0.75rem;
         left: 0.75rem;
         padding: 0.75rem 1rem;
         border-radius: 999px;
         background: var(--surface);
         border: 1px solid var(--border);
         box-shadow: var(--shadow);
         transform: translateY(-200%);
         transition: transform 0.2s ease;
         z-index: 10;
       }

       .skip-link:focus {
         transform: translateY(0);
         outline: none;
         box-shadow: var(--focus), var(--shadow);
       }

       main {
         display: grid;
         place-items: center;
         padding: 4rem 1rem;
       }

       .page-shell {
         width: min(100%, 44rem);
       }

       .hero {
         margin-bottom: 1.5rem;
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 0.5rem;
         margin: 0 0 0.75rem;
         padding: 0.35rem 0.75rem;
         border-radius: 999px;
         background: rgba(39, 94, 254, 0.1);
         color: var(--accent-strong);
         font-size: 0.875rem;
         font-weight: 600;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 4vw, 3.1rem);
         line-height: 1.05;
         letter-spacing: -0.04em;
       }

       .lead {
         max-width: 38rem;
         margin: 0.85rem 0 0;
         color: var(--muted);
         font-size: 1.02rem;
       }

       .card {
         padding: clamp(1.25rem, 2.5vw, 2rem);
         border: 1px solid rgba(157, 173, 191, 0.35);
         border-radius: var(--radius);
         background: rgba(255, 255, 255, 0.82);
         backdrop-filter: blur(16px);
         box-shadow: var(--shadow);
       }

       form {
         display: grid;
         gap: 1rem;
       }

       .form-field {
         display: grid;
         gap: 0.45rem;
       }

       label {
         font-size: 0.95rem;
         font-weight: 600;
         color: var(--text);
       }

       .required-mark {
         color: var(--error);
       }

       .field-help {
         margin: 0;
         color: var(--muted);
         font-size: 0.92rem;
       }

       input {
         width: 100%;
         border: 1px solid var(--border);
         border-radius: 14px;
         background: var(--surface);
         padding: 0.9rem 1rem;
         color: var(--text);
         font: inherit;
         transition: border-color 0.15s ease, box-shadow 0.15s ease, background-color 0.15s ease;
       }

       input::placeholder {
         color: #8a97a6;
       }

       input:hover {
         border-color: var(--border-strong);
       }

       input:focus {
         outline: none;
         border-color: var(--accent);
         box-shadow: var(--focus);
       }

       input[aria-invalid="true"] {
         border-color: var(--error);
         box-shadow: 0 0 0 4px rgba(180, 35, 24, 0.12);
       }

       .field-error {
         margin: 0;
         color: var(--error);
         font-size: 0.92rem;
         font-weight: 500;
       }

       .status-message {
         min-height: 1.25rem;
         margin: 0.25rem 0 0;
         color: var(--success);
         font-size: 0.95rem;
         font-weight: 600;
       }

       .actions {
         display: flex;
         justify-content: flex-end;
         padding-top: 0.25rem;
       }

       button {
         border: 0;
         border-radius: 999px;
         padding: 0.95rem 1.35rem;
         background: linear-gradient(180deg, var(--accent) 0%, var(--accent-strong) 100%);
         color: #fff;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
         box-shadow: 0 12px 24px rgba(39, 94, 254, 0.24);
         transition: transform 0.15s ease, box-shadow 0.15s ease, filter 0.15s ease;
       }

       button:hover {
         transform: translateY(-1px);
         filter: brightness(1.03);
       }

       button:focus-visible {
         outline: none;
         box-shadow: var(--focus), 0 12px 24px rgba(39, 94, 254, 0.24);
       }

       button:active {
         transform: translateY(0);
       }

       .visually-hidden {
         position: absolute;
         width: 1px;
         height: 1px;
         padding: 0;
         margin: -1px;
         overflow: hidden;
         clip: rect(0, 0, 0, 0);
         white-space: nowrap;
         border: 0;
       }

       @media (max-width: 640px) {
         main {
           padding: 3rem 1rem;
         }

         .card {
           border-radius: 18px;
         }

         .actions {
           justify-content: stretch;
         }

         button {
           width: 100%;
         }
       }

       @media (forced-colors: active) {
         .skip-link,
         .card,
         input,
         button {
           forced-color-adjust: auto;
         }
       }
