   <body>
     <a class="skip-link" href="#main">Skip to main content</a>
     <main id="main">
       <div class="page-shell">
         <header class="hero">
           <p class="eyebrow">Support</p>
           <h1>Contact our team</h1>
           <p class="lead">
             Send your details and we&apos;ll route your request to the right support specialist.
           </p>
         </header>

         <section class="card" aria-labelledby="contact-title">
           <h2 id="contact-title" class="visually-hidden">Support contact form</h2>
           <form id="support-form" novalidate>
             <div class="form-field">
               <label for="full-name">Full name <span class="required-mark" aria-hidden="true">*</span></label>
               <input
                 id="full-name"
                 name="fullName"
                 type="text"
                 autocomplete="name"
                 required
               />
               <p id="full-name-error" class="field-error" hidden></p>
             </div>

             <div class="form-field">
               <label for="email-address">Email address <span class="required-mark" aria-hidden="true">*</span></label>
               <input
                 id="email-address"
                 name="emailAddress"
                 type="email"
                 autocomplete="email"
                 required
               />
               <p id="email-address-error" class="field-error" hidden></p>
             </div>

             <div class="form-field">
               <label for="phone-number">Phone number</label>
               <p id="phone-number-help" class="field-help">
                 Format: include country code if you have one, for example +1 555 123 4567.
               </p>
               <input
                 id="phone-number"
                 name="phoneNumber"
                 type="tel"
                 autocomplete="tel"
                 aria-describedby="phone-number-help"
               />
             </div>

             <div class="actions">
               <button type="submit">Send message</button>
             </div>

             <p id="form-status" class="status-message" role="status" aria-live="polite"></p>
           </form>
         </section>
       </div>
     </main>

     <script>
       (() => {
         const form = document.getElementById('support-form');
         const fields = {
           fullName: {
             input: document.getElementById('full-name'),
             error: document.getElementById('full-name-error'),
             validate(value) {
               if (!value.trim()) {
                 return 'Error: Enter your full name.';
               }
               return '';
             },
           },
           emailAddress: {
             input: document.getElementById('email-address'),
             error: document.getElementById('email-address-error'),
             validate(value) {
               if (!value.trim()) {
                 return 'Error: Enter your email address.';
               }

               const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
               if (!emailPattern.test(value.trim())) {
                 return 'Error: Enter a valid email address, like name@example.com.';
               }

               return '';
             },
           },
         };

         const touched = new Set();
         const status = document.getElementById('form-status');

         function syncField(name, showError) {
           const field = fields[name];
           const message = field.validate(field.input.value);
           const hasError = Boolean(message) && showError;

           if (hasError) {
             field.input.setAttribute('aria-invalid', 'true');
           } else {
             field.input.removeAttribute('aria-invalid');
           }

           field.error.textContent = message;
           field.error.hidden = !hasError;

           if (hasError) {
             field.input.setAttribute('aria-describedby', `${field.error.id}`);
           } else {
             field.input.removeAttribute('aria-describedby');
           }

           return !message;
         }

         Object.entries(fields).forEach(([name, field]) => {
           field.input.addEventListener('blur', () => {
             touched.add(name);
             syncField(name, true);
           });

           field.input.addEventListener('input', () => {
             if (touched.has(name)) {
               syncField(name, true);
             } else {
               syncField(name, false);
             }
           });
         });

         form.addEventListener('submit', (event) => {
           event.preventDefault();
           status.textContent = '';

           const nameOrder = Object.keys(fields);
           const firstInvalid = nameOrder.find((name) => !syncField(name, true));

           if (firstInvalid) {
             fields[firstInvalid].input.focus();
             return;
           }

           status.textContent = 'All fields look good.';
         });
       })();
     </script>
   </body>
 </html>

